import AppKit
import SwiftUI

/// Official agent marks, drawn from embedded SVG so they render without bundled resources.
struct AgentIconView: View {
    let agent: AgentKind

    @Environment(\.colorScheme) private var colorScheme

    var body: some View {
        if let image = Self.image(for: agent, colorScheme: colorScheme) {
            Image(nsImage: image)
                .resizable()
                .renderingMode(image.isTemplate ? .template : .original)
                .interpolation(.high)
                .aspectRatio(contentMode: .fit)
                .foregroundStyle(ColermTheme.primaryText)
                .accessibilityLabel(agent.displayName)
        }
    }

    private struct CacheKey: Hashable {
        let agent: AgentKind
        let colorScheme: ColorScheme
    }

    @MainActor private static var cache: [CacheKey: NSImage] = [:]

    @MainActor private static func image(for agent: AgentKind, colorScheme: ColorScheme) -> NSImage? {
        let isTemplate = isMonochrome(agent)
        // Template images are tinted at draw time, so one image serves both appearances.
        let key = CacheKey(agent: agent, colorScheme: isTemplate ? .light : colorScheme)
        if let cached = cache[key] {
            return cached
        }
        // `currentColor` marks the parts of a mark drawn in the text color.
        let textColor = isTemplate ? "#000" : (colorScheme == .dark ? "#D9D9D9" : "#262626")
        let source = svg(for: agent).replacingOccurrences(of: "currentColor", with: textColor)
        guard let image = NSImage(data: Data(source.utf8)) else {
            return nil
        }
        image.size = NSSize(width: 24, height: 24)
        image.isTemplate = isTemplate
        cache[key] = image
        return image
    }

    /// Marks published in a single color follow the theme's text color.
    private static func isMonochrome(_ agent: AgentKind) -> Bool {
        switch agent {
        case .pi, .opencode, .grok, .factoryDroid, .cursor, .copilot, .kiro, .muse:
            return true
        default:
            return false
        }
    }

